const base64Data = $json.fileBase64;
const triggerItem = $('Gmail Trigger').item;
const binaryMeta = triggerItem.binary && triggerItem.binary['attachment_0'];
const mimeType = (binaryMeta && binaryMeta.mimeType) || 'application/pdf';
const fileName = (binaryMeta && binaryMeta.fileName) || 'attachment';
const email = triggerItem.json;

const isPdf = mimeType.includes('pdf');
const contentBlock = isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64Data } }
  : { type: 'image', source: { type: 'base64', media_type: mimeType, data: base64Data } };

const systemPrompt = `You extract structured data from business documents (invoices, receipts, forms).

Look at the attached document and return ONLY a JSON object, no markdown, no code fences, in exactly this shape:
{
  "document_type": "invoice" | "receipt" | "form" | "unknown",
  "vendor": "<string or null>",
  "total_amount": <number or null>,
  "document_date": "<YYYY-MM-DD or null>",
  "fields": [ { "name": "<field name>", "value": "<extracted value>", "page": <page number the value was found on, integer, 1-indexed> } ],
  "confident": true or false,
  "reason": "<one short sentence, for internal use only>"
}

Only set confident to true if the document is clearly legible and the key fields (vendor, total, date) were actually found. If the document is blank, unreadable, or not actually a business document, set confident to false and explain why in reason.`;

const requestBody = {
  model: 'claude-sonnet-5',
  max_tokens: 1536,
  system: systemPrompt,
  messages: [
    { role: 'user', content: [ contentBlock, { type: 'text', text: 'Extract the structured data from this document.' } ] }
  ],
};

let fromAddress = '';
if (email.from) {
  if (typeof email.from === 'string') {
    const m = email.from.match(/<([^>]+)>/);
    fromAddress = m ? m[1] : email.from;
  } else if (typeof email.from === 'object') {
    fromAddress = (email.from.value && email.from.value[0] && email.from.value[0].address) || email.from.text || '';
  }
}

return [{
  json: {
    requestBody,
    original: {
      fileName,
      mimeType,
      base64Data,
      emailSubject: email.subject,
      emailFrom: fromAddress,
      messageId: email.messageId || email.id,
    },
  },
}];

const response = $input.first().json;
const original = $('Build Extraction Prompt').item.json.original;

let text = '';
if (response.content && response.content[0] && response.content[0].text) {
  text = response.content[0].text;
}
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { document_type: 'unknown', vendor: null, total_amount: null, document_date: null, fields: [], confident: false, reason: 'Failed to parse model response as JSON' };
}

const confident = parsed.confident === true;
const status = confident ? 'success' : 'needs_review';

const documentRecord = {
  source: 'gmail-attachment',
  sourceRef: `${original.messageId}:${original.fileName}`,
  fileName: original.fileName,
  fileBase64: original.base64Data,
  documentType: parsed.document_type || 'unknown',
  vendor: parsed.vendor || null,
  totalAmount: parsed.total_amount || null,
  documentDate: parsed.document_date || null,
  extracted: { fields: parsed.fields || [], emailSubject: original.emailSubject, emailFrom: original.emailFrom },
  status,
  reason: parsed.reason || null,
};

const audit = {
  source: 'documents',
  actor: original.emailFrom || 'unknown',
  action: 'extract_document',
  details: { fileName: original.fileName, documentType: documentRecord.documentType, status },
  status,
  reason: parsed.reason || null,
};

return [{ json: { documentRecord, audit } }];
